/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);return <section className="anu-rich-itinerary"><header><small>ITINERARY</small><h2>{p.title}</h2>{p.subtitle&&<p>{p.subtitle}</p>}</header><ol>{(p.legs??[]).map(x=><li key={x.id}><span>{x.icon??({parking:"P",flight:"✈",hotel:"⌂",rail:"↔",car:"◆",activity:"★"}[x.kind]??"•")}</span><div><small>{x.start}{x.end&&` — ${x.end}`}</small><strong>{x.title}</strong>{x.subtitle&&<p>{x.subtitle}</p>}</div>{x.status&&<b>{x.status}</b>}</li>)}</ol></section>}
